<?php
declare(strict_types=1);
namespace EnglAI\Learning;
final class ListeningSessionService{
 public const QUESTIONS=10,TIMER=10,MAX_PLAYS=2;
 public function __construct(private readonly \PDO $pdo){}
 public static function balancedPositions():array{$counts=[3,3,2,2];shuffle($counts);$pool=[];foreach($counts as$position=>$count)for($i=0;$i<$count;$i++)$pool[]=$position;for($try=0;$try<100;$try++){shuffle($pool);$valid=true;for($i=2;$i<count($pool);$i++)if($pool[$i]===$pool[$i-1]&&$pool[$i]===$pool[$i-2]){$valid=false;break;}if($valid)return$pool;}throw new \RuntimeException('Tidak dapat menyeimbangkan posisi jawaban Listening.');}
 private function snapshotize(array$items,?string$previousFingerprint):array{for($try=0;$try<12;$try++){shuffle($items);$sequence=implode(',',array_column($items,'activity_id'));$fingerprint=hash('sha256',$sequence);if($previousFingerprint===null||$fingerprint!==$previousFingerprint)break;}$positions=self::balancedPositions();foreach($items as$i=>&$item){$original=array_values($item['options']);$originalAnswer=(string)$item['answer'];$correctIndex=ord($originalAnswer)-65;if($correctIndex<0||$correctIndex>3)throw new \RuntimeException('Answer key Listening tidak valid.');$options=[];foreach($original as$index=>$text)$options[]=['id'=>'lo'.$item['activity_id'].'_'.substr(hash('sha256',$item['activity_id'].'|'.$index.'|'.$text),0,8),'text'=>(string)$text];$correct=$options[$correctIndex];$distractors=array_values(array_filter($options,fn($option)=>$option['id']!==$correct['id']));shuffle($distractors);array_splice($distractors,$positions[$i],0,[$correct]);$item['options']=$distractors;$item['correct_option_id']=$correct['id'];$item['correct_letter']=chr(65+$positions[$i]);unset($item['answer']);}unset($item);$ids=array_column($items,'activity_id');$texts=array_map(fn($item)=>self::norm((string)$item['question']),$items);if(count($items)!==self::QUESTIONS||count(array_unique($ids))!==self::QUESTIONS||count(array_unique($texts))!==self::QUESTIONS)throw new \RuntimeException('Snapshot Listening harus memiliki 10 soal unik.');return['questions'=>$items,'sequence_fingerprint'=>$fingerprint,'correct_distribution'=>array_count_values(array_map(fn($position)=>chr(65+$position),$positions))];}
 public function start(int$classroomId,int$memberId,string$level,bool$force=false):int{$level=Level::validate($level);if(!$force){$q=$this->pdo->prepare("SELECT id FROM listening_sessions WHERE classroom_id=? AND member_id=? AND level=? AND status='active' ORDER BY id DESC LIMIT 1");$q->execute([$classroomId,$memberId,$level]);if($id=(int)$q->fetchColumn())return$id;}$q=$this->pdo->prepare("SELECT id FROM classroom_lesson_plans WHERE classroom_id=? AND is_active=1 ORDER BY version DESC LIMIT 1");$q->execute([$classroomId]);$plan=(int)$q->fetchColumn();if(!$plan)throw new \RuntimeException('Listening content sedang dipersiapkan.');$q=$this->pdo->prepare("SELECT l.*,MAX(CASE WHEN s.member_id=? THEN a.answered_at END) last_used FROM learning_activities l LEFT JOIN listening_session_answers a ON a.activity_id=l.id LEFT JOIN listening_sessions s ON s.id=a.listening_session_id WHERE l.classroom_id=? AND l.lesson_plan_id=? AND l.skill='listening' AND l.level=? AND l.status='ready' GROUP BY l.id ORDER BY last_used IS NULL DESC,last_used ASC,RAND()");$q->execute([$memberId,$classroomId,$plan,$level]);$pool=[];$ids=[];$texts=[];foreach($q->fetchAll()as$row){$c=json_decode((string)$row['content_json'],true)?:[];$text=self::norm((string)($c['question']??''));if($text===''||isset($texts[$text])||isset($ids[(int)$row['id']])||count($c['options']??[])!==4||!isset($c['answer']))continue;$pool[]=['activity_id'=>(int)$row['id'],'title'=>(string)$row['title'],'question'=>(string)$c['question'],'options'=>array_values($c['options']),'answer'=>(string)$c['answer'],'explanation'=>(string)($c['explanation']??''),'script'=>(string)($c['script']??$c['transcript']??''),'transcript'=>(string)($c['transcript']??$c['script']??''),'language'=>(string)($c['language']??'en-US'),'rate'=>(float)($c['rate']??1),'pitch'=>(float)($c['pitch']??1)];$ids[(int)$row['id']]=true;$texts[$text]=true;}if(count($pool)<self::QUESTIONS)throw new \RuntimeException('Listening content belum memiliki 10 soal unik.');$items=array_slice($pool,0,self::QUESTIONS);$previous=$this->pdo->prepare("SELECT snapshot_json FROM listening_sessions WHERE classroom_id=? AND member_id=? AND lesson_plan_id=? AND level=? ORDER BY id DESC LIMIT 1");$previous->execute([$classroomId,$memberId,$plan,$level]);$old=json_decode((string)($previous->fetchColumn()?:''),true)?:[];$snapshot=$this->snapshotize($items,$old['sequence_fingerprint']??null);$this->pdo->prepare("INSERT INTO listening_sessions(classroom_id,member_id,lesson_plan_id,level,snapshot_json,started_at) VALUES(?,?,?,?,?,NOW())")->execute([$classroomId,$memberId,$plan,$level,json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);return(int)$this->pdo->lastInsertId();}
 public function get(int$id,int$memberId,bool$lock=false):array{$q=$this->pdo->prepare('SELECT * FROM listening_sessions WHERE id=? AND member_id=?'.($lock?' FOR UPDATE':''));$q->execute([$id,$memberId]);$s=$q->fetch();if(!$s)throw new \RuntimeException('Listening session tidak ditemukan.');$s['snapshot']=json_decode((string)$s['snapshot_json'],true)?:[];return$s;}
 private function current(array$s):?array{return$s['snapshot']['questions'][(int)$s['current_position']]??null;}
 public function publicState(array$s):array{$q=$this->current($s);if(!$q)return['completed'=>true,'current_index'=>(int)$s['current_position'],'score'=>(int)$s['score']];$remaining=$s['question_started_at']?max(0,self::TIMER-(time()-strtotime((string)$s['question_started_at']))):self::TIMER;return['completed'=>false,'session_id'=>(int)$s['id'],'level'=>$s['level'],'current_index'=>(int)$s['current_position'],'score'=>(int)$s['score'],'timer_seconds'=>self::TIMER,'timer_remaining'=>$remaining,'play_count'=>(int)$s['replay_count'],'timer_started_at'=>$s['question_started_at'],'question'=>['id'=>(int)$q['activity_id'],'title'=>$q['title'],'question'=>$q['question'],'options'=>$q['options'],'script'=>$q['script'],'language'=>$q['language'],'rate'=>$q['rate'],'pitch'=>$q['pitch']]];}
 public function play(int$id,int$memberId):array{$this->pdo->beginTransaction();try{$s=$this->get($id,$memberId,true);if($s['status']!=='active'||(int)$s['replay_count']>=self::MAX_PLAYS)throw new \RuntimeException('PLAY_LIMIT');$count=(int)$s['replay_count']+1;$this->pdo->prepare('UPDATE listening_sessions SET replay_count=? WHERE id=?')->execute([$count,$id]);$this->pdo->commit();return['success'=>true,'play_count'=>$count,'remaining'=>self::MAX_PLAYS-$count];}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 public function begin(int$id,int$memberId):void{$this->pdo->prepare("UPDATE listening_sessions SET question_started_at=COALESCE(question_started_at,NOW()) WHERE id=? AND member_id=? AND status='active' AND replay_count>=1")->execute([$id,$memberId]);}
 public function answer(int$id,int$memberId,int$activityId,?string$selected,bool$timeout):array{$this->pdo->beginTransaction();try{$s=$this->get($id,$memberId,true);$dup=$this->pdo->prepare('SELECT * FROM listening_session_answers WHERE listening_session_id=? AND activity_id=?');$dup->execute([$id,$activityId]);if($a=$dup->fetch()){$this->pdo->commit();return$this->response($a,$s,true);}$q=$this->current($s);if($s['status']!=='active'||!$q||(int)$q['activity_id']!==$activityId)throw new \RuntimeException('STALE_QUESTION');$elapsed=$s['question_started_at']?max(0,(time()-strtotime((string)$s['question_started_at']))*1000):0;$timed=$timeout||($s['question_started_at']!==null&&$elapsed>self::TIMER*1000);$optionIds=array_map('strval',array_column($q['options'],'id'));if(!$timed&&($selected===null||!in_array($selected,$optionIds,true)))throw new \InvalidArgumentException('INVALID_OPTION');$correct=!$timed&&hash_equals((string)$q['correct_option_id'],(string)$selected);$result=$timed?'timed_out':($correct?'correct':'incorrect');$points=$correct?10:0;$this->pdo->prepare("INSERT INTO listening_session_answers(listening_session_id,activity_id,selected_answer,result,response_ms,score,replay_count,answered_at) VALUES(?,?,?,?,?,?,?,NOW())")->execute([$id,$activityId,$selected,$result,$elapsed,$points,(int)$s['replay_count']]);$key=hash('sha256','listening-session-'.$id.'-'.$activityId);$this->pdo->prepare("INSERT INTO learning_attempts(classroom_id,member_id,activity_id,idempotency_key,status,answer_json,score,maximum_score,feedback,assessment_source,started_at,submitted_at,completed_at) VALUES(?,?,?,?,'completed',?,?,100,?,'objective',NOW(),NOW(),NOW()) ON DUPLICATE KEY UPDATE id=id")->execute([(int)$s['classroom_id'],$memberId,$activityId,$key,json_encode(['selected_option_id'=>$selected,'correct_option_id'=>$q['correct_option_id'],'is_correct'=>$correct,'timed_out'=>$timed]),$points*10,$q['explanation']]);$next=(int)$s['current_position']+1;$done=$next>=self::QUESTIONS;$this->pdo->prepare("UPDATE listening_sessions SET current_position=?,score=score+?,replay_count=0,question_started_at=NULL,status=?,completed_at=IF(?='completed',NOW(),NULL) WHERE id=?")->execute([$next,$points,$done?'completed':'active',$done?'completed':'active',$id]);$this->pdo->commit();$fresh=$this->get($id,$memberId);return$this->response(['activity_id'=>$activityId,'selected_answer'=>$selected,'result'=>$result,'score'=>$points],$fresh,false,$q);}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 private function response(array$a,array$s,bool$duplicate,array$q=null):array{$q??=$this->find($s,(int)$a['activity_id']);$correctId=(string)$q['correct_option_id'];$correctText='';$selectedLetter=null;$selectedText=null;foreach($q['options']as$index=>$option){if((string)$option['id']===$correctId)$correctText=(string)$option['text'];if((string)$option['id']===(string)($a['selected_answer']??'')){$selectedLetter=chr(65+$index);$selectedText=(string)$option['text'];}}return['success'=>true,'result'=>$a['result'],'correct'=>$a['result']==='correct','points'=>(int)$a['score'],'selected_option_id'=>$a['selected_answer'],'selected_answer'=>$selectedLetter,'selected_answer_text'=>$selectedText,'correct_option_id'=>$correctId,'correct_answer'=>(string)$q['correct_letter'],'correct_answer_text'=>$correctText,'score'=>(int)$s['score'],'current_index'=>(int)$s['current_position'],'completed'=>$s['status']==='completed','duplicate'=>$duplicate,'next_state'=>$this->publicState($s)];}
 private function find(array$s,int$activityId):array{foreach($s['snapshot']['questions']??[]as$q)if((int)$q['activity_id']===$activityId)return$q;throw new \RuntimeException('QUESTION_NOT_FOUND');}
 public function review(int$id,int$memberId):array{$s=$this->get($id,$memberId);if($s['status']!=='completed')throw new \RuntimeException('SESSION_ACTIVE');$q=$this->pdo->prepare('SELECT * FROM listening_session_answers WHERE listening_session_id=? ORDER BY id');$q->execute([$id]);$rows=[];foreach($q->fetchAll()as$a){$item=$this->find($s,(int)$a['activity_id']);$correctText='';$selectedText=null;$selectedLetter=null;foreach($item['options']as$index=>$option){if((string)$option['id']===(string)$item['correct_option_id'])$correctText=(string)$option['text'];if((string)$option['id']===(string)($a['selected_answer']??'')){$selectedText=(string)$option['text'];$selectedLetter=chr(65+$index);}}$explanation=trim((string)$item['explanation']);if($explanation===''||preg_match('/listen( to the audio)? carefully|find the answer/i',$explanation)){$context=mb_substr(trim((string)($item['transcript']??$item['script']??'')),0,320);$explanation=$context!==''?'The audio context states: “'.$context.'” Therefore, the correct answer is “'.$correctText.'”.':'The correct answer supported by the stored listening item is “'.$correctText.'”.';}$rows[]=$a+['question'=>$item['question'],'options'=>$item['options'],'selected_answer'=>$selectedLetter,'selected_answer_text'=>$selectedText,'correct_answer'=>$item['correct_letter'],'correct_answer_text'=>$correctText,'explanation'=>$explanation,'script'=>$item['script']];}return$rows;}
 public static function norm(string$v):string{return mb_strtolower(trim(preg_replace('/\s+/u',' ',$v)??$v));}
}
